cssCode:
.clinical-card {
  width: 280px; height: 160px;
  background: rgba(255, 255, 255, 0.05); backdrop-filter: blur(15px);
  border: 1px solid rgba(0, 212, 255, 0.3); border-radius: 20px;
  display: flex; flex-direction: column; justify-content: center; padding: 20px;
  box-sizing: border-box; color: #fff; font-family: sans-serif;
  transition: transform 0.3s ease, box-shadow 0.3s ease; cursor: pointer;
}
.clinical-card:hover {
  transform: translateY(-10px);
  box-shadow: 0 15px 30px rgba(0, 212, 255, 0.2);
  border-color: #00d4ff;
}
.pulse-line {
  width: 100%; height: 3px; background: #00d4ff; margin-top: 15px;
  position: relative; overflow: hidden;
}
.pulse-line::after {
  content: ''; position: absolute; top: 0; left: -100%;
  width: 50%; height: 100%; background: #fff;
  animation: scanLine 2s infinite;
}
@keyframes scanLine { 100% { left: 200%; } }

